FROM (SELECT business_date, hierarchy_level, account, portfolio_type, department, strategy, program, sub_program, analytic_value, tenor, curve_type, analytic_name, analytic_type, node_level,rating,currency,node
FROM "risk_prod"."rmv_analytics"
WHERE analytic_type IN ('DV01', 'PV', 'CS01', 'VOLATILITY_10YR','VAR_10YR')
  AND portfolio_type IN ('TOTAL_FUND_BY_ACCOUNT', 'IP')
  and (confidence_level is null or confidence_level = 0.95)
  AND (
    (analytic_type IN ('PV', 'VOLATILITY_10YR','VAR_10YR') AND hierarchy_level IN ('CPPIB-ALL', 'DEPARTMENT', 'ACCOUNT', 'POOL', 'STRATEGY', 'PROGRAM', 'SUB-PROGRAM'))
    OR (analytic_type IN ('CS01', 'DV01') AND hierarchy_level = 'MODEL_PORTFOLIO')
  )) AS "New custom SQL"
WHERE "department" IN ('Total Fund Management') AND date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) = date_trunc('day', CAST(CAST(PARSE_DATETIME('2025-06-11 00:00:00', 'yyyy-MM-dd HH:mm:ss') AS TIMESTAMP) AS TIMESTAMP)) AND CASE WHEN "account" IS NULL AND "portfolio_type" = 'IP' THEN 'TOTAL FUND' ELSE "account" END IN ('TOTAL FUND') AND "analytic_type" IN ('VOLATILITY_10YR', 'PV') AND "hierarchy_level" = 'DEPARTMENT'
GROUP BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP))
ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) DESC
LIMIT 2

